import{c as e,Q as t,j as o,m as r}from"./chunks/framework.DjobWxAB.js";const u=JSON.parse('{"title":"Level 1 개발자 가이드","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/Guides/developer-level-1.md","filePath":"ko/manual/Guides/developer-level-1.md","lastUpdated":1779182288000}'),l={name:"ko/manual/Guides/developer-level-1.md"};function n(h,a,s,i,m,d){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="level-1-개발자-가이드" tabindex="-1">Level 1 개발자 가이드 <a class="header-anchor" href="#level-1-개발자-가이드" aria-label="Permalink to &quot;Level 1 개발자 가이드&quot;">​</a></h1><p><strong>미리 정의된 동작·명령</strong>으로 로봇을 다루는 경로입니다. <strong>Level 0 가이드와 선후 관계는 없습니다.</strong> 관절·토크를 직접 다루지 않고 앱·통합·ROS2로 보행·모션을 올리려면 여기서 시작하면 됩니다.</p><h2 id="lv1-sdk가-하는-일" tabindex="-1">LV1 SDK가 하는 일 <a class="header-anchor" href="#lv1-sdk가-하는-일" aria-label="Permalink to &quot;LV1 SDK가 하는 일&quot;">​</a></h2><ul><li><strong>단일 명령</strong> 기반 모션·보행 실행, <strong>RBQ APP</strong> 명령 세트와 연동</li><li>API 제공: C/C++, Python, <strong>ROS2</strong></li><li>ROS2/API로 <strong>보행 모드·고수준 모션</strong>을 시스템에 붙이거나 연동(앱 개발·시스템 통합·빠른 프로토타이핑)</li><li><strong><a href="/RBQ/ko/software/API.html">API</a></strong> / <strong><a href="/RBQ/ko/software/ROS2.html">ROS2</a></strong> 로 시작; <strong>C++ DDS 예제</strong>(저수준 스타일)는 <a href="/RBQ/ko/software/examples/rbq_example_Level0.html">rbq_example_level_0</a>, <a href="/RBQ/ko/software/rbq-sdk.html">RBQ SDK</a> 참고</li></ul><p>센서·액추에이터를 <strong>직접</strong> 제어(관절 레벨 제어)가 필요하면 <a href="/RBQ/ko/manual/Guides/developer-level-0.html">Level 0 개발자 가이드</a>를 참고하세요. 현장에서 RBQGUI만으로 운영할 계획이면 <a href="/RBQ/ko/manual/Guides/common-guide.html">공통 가이드</a>로 충분합니다.</p><h2 id="사전-준비" tabindex="-1">사전 준비 <a class="header-anchor" href="#사전-준비" aria-label="Permalink to &quot;사전 준비&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>OS·빌드</td><td><a href="/RBQ/ko/software/developers-guide.html">개발자 가이드</a> - 시뮬/실기 공통 환경</td></tr><tr><td>개념</td><td><a href="/RBQ/ko/software/Concept.html">Concept</a>에서 <strong>High Level / LV1</strong> 확인</td></tr><tr><td>네트워크</td><td>실제 로봇 사용 시 <a href="/RBQ/ko/manual/Operation/controller-wifi-connect.html">컨트롤러·Wi-Fi</a> 안내와 동일하게 로봇과 통신 가능한지 확인</td></tr></tbody></table><h2 id="권장-순서" tabindex="-1">권장 순서 <a class="header-anchor" href="#권장-순서" aria-label="Permalink to &quot;권장 순서&quot;">​</a></h2><ol><li><a href="/RBQ/ko/manual/Guides/common-guide.html">공통 가이드</a> 숙지합니다.</li><li><a href="/RBQ/ko/software/developers-guide.html">개발자 가이드</a> 숙지합니다.</li><li><strong><a href="/RBQ/ko/software/API.html">API</a></strong>: C++ 문서에서 필요한 API를 숙지합니다.</li><li><strong><a href="/RBQ/ko/software/ROS2.html">ROS2</a></strong>: 퀵스타트를 따라 구독·활용하며 먼저 예제로 테스트 후 개발 진행합니다.</li><li><strong>C++ SDK·예제</strong>: <a href="/RBQ/ko/software/rbq-sdk.html">RBQ SDK</a>, <a href="/RBQ/ko/software/examples/rbq_example_Level0.html">rbq_example_level_0</a>(LV0 스타일); LV1 모션은 <a href="/RBQ/ko/software/API.html">API</a>, <a href="/RBQ/ko/software/ROS2.html">ROS2</a></li><li><strong>업데이트·문의하기</strong> - <a href="/RBQ/ko/manual/GUI/gui-software-update.html">GUI 소프트웨어 업데이트 방법</a>, <a href="/RBQ/ko/manual/GUI/robot-software-update.html">로봇 소프트웨어 업데이트 방법</a>, <a href="/RBQ/ko/software/Troubleshooting/error-reporting.html">문의하기</a></li></ol><h2 id="gui·운영-문서와의-연계" tabindex="-1">GUI·운영 문서와의 연계 <a class="header-anchor" href="#gui·운영-문서와의-연계" aria-label="Permalink to &quot;GUI·운영 문서와의 연계&quot;">​</a></h2><p>고수준 명령도 <strong>현장 RBQGUI</strong>와 동시에 쓰일 수 있습니다. <strong>Sit / Stance / EMERGENCY</strong> 흐름과 충돌하지 않게 설계하세요 - <a href="/RBQ/ko/manual/GUI/introduction.html">GUI 소개</a>, <a href="/RBQ/ko/manual/GUI/basic-motion-command.html">기본 동작</a>.</p><p>보행 품질·센서: <a href="/RBQ/ko/manual/Troubleshooting/calibration-tuning.html">캘리브레이션 및 튜닝</a>, <a href="/RBQ/ko/manual/GUI/state-monitoring.html">상태 모니터링</a>. 버전: <a href="/RBQ/ko/manual/GUI/robot-software-update.html">로봇 소프트웨어 업데이트</a>.</p><h2 id="유의사항" tabindex="-1">유의사항 <a class="header-anchor" href="#유의사항" aria-label="Permalink to &quot;유의사항&quot;">​</a></h2><p>RL·커스텀 보행은 여전히 <strong>낙상·충돌</strong> 위험이 있습니다.<br> 시뮬레이션과 안전 거리를 확보한 환경에서 검증하고, 비상 시 GUI 개입이 가능해야 합니다 - <a href="/RBQ/ko/manual/GUI/introduction.html">GUI 소개</a>, <a href="/RBQ/ko/manual/GUI/basic-motion-command.html">기본 동작</a>, <a href="/RBQ/ko/manual/Safety/emergency-stop-procedures.html">비상 정지</a>.</p><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/RBQ/ko/software/Concept.html">Concept</a></li><li><a href="/RBQ/ko/software/developers-guide.html">개발자 가이드</a></li><li><a href="/RBQ/ko/software/API.html">API</a></li><li><a href="/RBQ/ko/software/ROS2.html">ROS2</a></li><li><a href="/RBQ/ko/software/rbq-sdk.html">RBQ SDK</a> · <a href="/RBQ/ko/software/examples/rbq_example_Level0.html">rbq_example_level_0</a></li><li><a href="/RBQ/ko/manual/GUI/gui-software-update.html">GUI 소프트웨어 업데이트 방법</a></li><li><a href="/RBQ/ko/manual/GUI/robot-software-update.html">로봇 소프트웨어 업데이트 방법</a></li><li><a href="/RBQ/ko/software/Troubleshooting/error-reporting.html">문의하기</a></li></ul>',16)])])}const R=e(l,[["render",n]]);export{u as __pageData,R as default};
